algorithms.pseudocode:
allPaths(m, n):
  if m=0 and n=0: return [[]]
  result = []
  if m>0: for p in allPaths(m-1,n): result.append(['E']+p)
  if n>0: for p in allPaths(m,n-1): result.append(['N']+p)
  return result

qBinomial(m, n):
  if n=0 or m=0: return {0: 1}
  a = qBinomial(m, n-1)
  b = qBinomial(m-1, n)
  return a + q^n * b  (polynomial addition and multiplication)
